private void executeSafeAction(String taskAction) {
  switch (taskAction) {
    case "sleep" -> { try { TimeUnit.SECONDS.sleep(5); } catch (InterruptedException ignored) { Thread.currentThread().interrupt(); } }
    case "ping" -> log.info("ping simulated");
    default -> log.warn("rejected action: {}", taskAction);
  }
}
